def api_courses(request):
    if request.method != "GET":
        return JsonResponse({"error": "Method not allowed."}, status=405)
    user, error = _api_user_from_request(request)
    if error:
        return error
    rows = [
        {
            "id": course.id,
            "code": course.code,
            "title": course.title,
            "status": course.status,
            "enrollment_mode": course.enrollment_mode,
        }
        for course in visible_courses(user).filter(status__in=[Course.Status.PUBLISHED, Course.Status.DRAFT, Course.Status.ARCHIVED])
    ]
    return JsonResponse({"courses": rows})

