def grading_queue(request):
    qs = visible_submissions(request.user).select_related("assignment", "assignment__course", "student")
    form = SearchForm(request.GET)
    if form.is_valid():
        q = form.cleaned_data.get("q")
        status = form.cleaned_data.get("status")
        if status:
            qs = qs.filter(status=status)
        qs = _filter_text(qs, q, ["assignment__title", "assignment__course__code", "student__username", "student__email"])
    qs = qs.exclude(status=Submission.Status.NOT_STARTED)
    return render(request, "lms/grading_queue.html", {"submissions": qs, ...})

